import {selectProject} from './chapters.js';
const project=([lng,lat])=>[(lng+75)*13.6+14,(6-lat)*13.6+4];
const ns='http://www.w3.org/2000/svg';
const points=[['1303536','pitinga','Pitinga · AM','○',-80,-30],['5213087','serra','Serra Verde · GO','●',-120,-30],['5214903','carina','Carina · GO','▲',25,-25],['3104007','araxa','Araxá · MG','□',45,5],['3151800','caldeira','Poços de Caldas · 3 fichas','③',-175,45]];
async function draw(){try{const [states,towns]=await Promise.all(['brazil-states','project-municipalities'].map(n=>fetch(`assets/${n}.geojson`).then(r=>r.json())));const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 600 570');svg.setAttribute('role','group');svg.setAttribute('aria-label','Mapa dos projetos. Referências municipais do IBGE.');for(const f of states.features){const polygons=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];const path=document.createElementNS(ns,'path');path.setAttribute('d',polygons.map(p=>p.map(r=>r.map((c,i)=>(i?'L':'M')+project(c).join(',')).join(' ')+'Z').join(' ')).join(' '));path.setAttribute('class','project-state');svg.append(path)}for(const [code,id,name,symbol,dx,dy] of points){const f=towns.features.find(f=>String(f.properties.codarea)===code);const c=f.geometry.coordinates.flat(f.geometry.type==='MultiPolygon'?2:1);const lngs=c.map(c=>c[0]),lats=c.map(c=>c[1]);const [x,y]=project([(Math.min(...lngs)+Math.max(...lngs))/2,(Math.min(...lats)+Math.max(...lats))/2]);const addHeroPoint=()=>{const hero=document.querySelector('#hero-map svg');if(hero){hero.insertAdjacentHTML('beforeend',`<circle class="hero-location-ring" cx="${x}" cy="${y}" r="11"/><circle class="hero-location" cx="${x}" cy="${y}" r="4"><title>Referência municipal: ${name}</title></circle>`)}};if(document.querySelector('#hero-map svg'))addHeroPoint();else document.addEventListener('atlas-map-ready',addHeroPoint,{once:true});const g=document.createElementNS(ns,'g');g.setAttribute('class','project-point');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',name);g.setAttribute('aria-pressed',String(id==='serra'));g.dataset.projectPoint=id;g.innerHTML=`<path d="M${x},${y} L${x+dx},${y+dy}" stroke="#74846b" fill="none"/><circle cx="${x}" cy="${y}" r="14" fill="transparent"/><text x="${x}" y="${y+5}" text-anchor="middle" class="point-symbol">${symbol}</text><rect x="${x+dx-6}" y="${y+dy-17}" width="${name.length*7.6+12}" height="26" rx="3" fill="#18211a"/><text x="${x+dx}" y="${y+dy}" class="point-label">${name}</text>`;const activate=()=>selectProject(id);g.addEventListener('click',activate);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}});svg.append(g)}document.querySelector('#project-map').append(svg);selectProject('serra')}catch{document.querySelector('#project-map').innerHTML='<p>Mapa indisponível. Explore todos os projetos pelo seletor ao lado.</p>'}}
draw();
